     1→/**
     2→ * FKExcelUploader - Excel file upload component with drag & drop.
     3→ *
     4→ * Handles file selection, validation, and upload for the
     5→ * Facturación MX automation feature.
     6→ */
     7→
     8→import React, { useState, useCallback, useRef } from 'react';
     9→import {
    10→  Box,
    11→  Typography,
    12→  Button,
    13→  Paper,
    14→  LinearProgress,
    15→  Alert,
    16→  AlertTitle,
    17→  List,
    18→  ListItem,
    19→  ListItemIcon,
    20→  ListItemText,
    21→  Chip,
    22→  IconButton,
    23→} from '@mui/material';
    24→import {
    25→  CloudUpload as CloudUploadIcon,
    26→  InsertDriveFile as FileIcon,
    27→  Error as ErrorIcon,
    28→  Close as CloseIcon,
    29→  Warning as WarningIcon,
    30→} from '@mui/icons-material';
    31→import type { ExcelValidationResponse, ExcelValidationError } from '../../types/finance';
    32→import financeService from '../../services/financeService';
    33→
    34→interface FKExcelUploaderProps {
    35→  /** Callback when upload and validation succeeds */
    36→  onUploadSuccess: (response: ExcelValidationResponse) => void;
    37→  /** Callback when upload fails */
    38→  onUploadError: (error: string) => void;
    39→  /** Maximum file size in MB (default: 10) */
    40→  maxSizeMB?: number;
    41→  /** Accepted file formats (default: .xlsx, .xls) */
    42→  acceptedFormats?: string[];
    43→  /** Whether the uploader is disabled */
    44→  disabled?: boolean;
    45→}
    46→
    47→/**
    48→ * Excel file uploader with drag & drop support.
    49→ */
    50→const FKExcelUploader: React.FC<FKExcelUploaderProps> = ({
    51→  onUploadSuccess,
    52→  onUploadError,
    53→  maxSizeMB = 10,
    54→  acceptedFormats = ['.xlsx', '.xls'],
    55→  disabled = false,
    56→}) => {
    57→  const [isDragging, setIsDragging] = useState(false);
    58→  const [selectedFile, setSelectedFile] = useState<File | null>(null);
    59→  const [uploading, setUploading] = useState(false);
    60→  const [uploadProgress, setUploadProgress] = useState(0);
    61→  const [validationErrors, setValidationErrors] = useState<ExcelValidationError[]>([]);
    62→  const [fileError, setFileError] = useState<string | null>(null);
    63→
    64→  const fileInputRef = useRef<HTMLInputElement>(null);
    65→
    66→  const maxSizeBytes = maxSizeMB * 1024 * 1024;
    67→
    68→  /**
    69→   * Validate selected file.
    70→   */
    71→  const validateFile = useCallback(
    72→    (file: File): string | null => {
    73→      // Check file extension
    74→      const fileName = file.name.toLowerCase();
    75→      const hasValidExtension = acceptedFormats.some((format) =>
    76→        fileName.endsWith(format.toLowerCase())
    77→      );
    78→      if (!hasValidExtension) {
    79→        return `Formato no válido. Use: ${acceptedFormats.join(', ')}`;
    80→      }
    81→
    82→      // Check file size
    83→      if (file.size > maxSizeBytes) {
    84→        return `El archivo excede el tamaño máximo de ${maxSizeMB}MB`;
    85→      }
    86→
    87→      return null;
    88→    },
    89→    [acceptedFormats, maxSizeBytes, maxSizeMB]
    90→  );
    91→
    92→  /**
    93→   * Handle file selection from input or drop.
    94→   */
    95→  const handleFileSelect = useCallback(
    96→    (file: File) => {
    97→      setFileError(null);
    98→      setValidationErrors([]);
    99→
   100→      const error = validateFile(file);
   101→      if (error) {
   102→        setFileError(error);
   103→        return;
   104→      }
   105→
   106→      setSelectedFile(file);
   107→    },
   108→    [validateFile]
   109→  );
   110→
   111→  /**
   112→   * Handle drag events.
   113→   */
   114→  const handleDragEnter = useCallback((e: React.DragEvent) => {
   115→    e.preventDefault();
   116→    e.stopPropagation();
   117→    setIsDragging(true);
   118→  }, []);
   119→
   120→  const handleDragLeave = useCallback((e: React.DragEvent) => {
   121→    e.preventDefault();
   122→    e.stopPropagation();
   123→    setIsDragging(false);
   124→  }, []);
   125→
   126→  const handleDragOver = useCallback((e: React.DragEvent) => {
   127→    e.preventDefault();
   128→    e.stopPropagation();
   129→  }, []);
   130→
   131→  const handleDrop = useCallback(
   132→    (e: React.DragEvent) => {
   133→      e.preventDefault();
   134→      e.stopPropagation();
   135→      setIsDragging(false);
   136→
   137→      if (disabled) return;
   138→
   139→      const files = e.dataTransfer.files;
   140→      if (files.length > 0) {
   141→        handleFileSelect(files[0]);
   142→      }
   143→    },
   144→    [disabled, handleFileSelect]
   145→  );
   146→
   147→  /**
   148→   * Handle file input change.
   149→   */
   150→  const handleInputChange = useCallback(
   151→    (e: React.ChangeEvent<HTMLInputElement>) => {
   152→      const files = e.target.files;
   153→      if (files && files.length > 0) {
   154→        handleFileSelect(files[0]);
   155→      }
   156→    },
   157→    [handleFileSelect]
   158→  );
   159→
   160→  /**
   161→   * Trigger file input click.
   162→   */
   163→  const handleBrowseClick = useCallback(() => {
   164→    if (fileInputRef.current) {
   165→      fileInputRef.current.click();
   166→    }
   167→  }, []);
   168→
   169→  /**
   170→   * Clear selected file.
   171→   */
   172→  const handleClearFile = useCallback(() => {
   173→    setSelectedFile(null);
   174→    setFileError(null);
   175→    setValidationErrors([]);
   176→    if (fileInputRef.current) {
   177→      fileInputRef.current.value = '';
   178→    }
   179→  }, []);
   180→
   181→  /**
   182→   * Upload file to backend.
   183→   */
   184→  const handleUpload = useCallback(async () => {
   185→    if (!selectedFile) return;
   186→
   187→    setUploading(true);
   188→    setUploadProgress(0);
   189→    setValidationErrors([]);
   190→    setFileError(null);
   191→
   192→    try {
   193→      // Simulate progress
   194→      const progressInterval = setInterval(() => {
   195→        setUploadProgress((prev) => Math.min(prev + 10, 90));
   196→      }, 200);
   197→
   198→      const response = await financeService.uploadExcel(selectedFile);
   199→
   200→      clearInterval(progressInterval);
   201→      setUploadProgress(100);
   202→
   203→      if (response.errors.length > 0) {
   204→        setValidationErrors(response.errors);
   205→      }
   206→
   207→      // Still call success if we have valid data
   208→      if (response.valid_rows > 0) {
   209→        onUploadSuccess(response);
   210→      } else if (response.errors.length > 0) {
   211→        onUploadError('No se encontraron registros válidos en el archivo');
   212→      }
   213→    } catch (error: unknown) {
   214→      const errorMessage =
   215→        error instanceof Error
   216→          ? error.message
   217→          : (error as { response?: { data?: { detail?: string } } })?.response?.data?.detail ||
   218→            'Error al cargar el archivo';
   219→      setFileError(errorMessage);
   220→      onUploadError(errorMessage);
   221→    } finally {
   222→      setUploading(false);
   223→    }
   224→  }, [selectedFile, onUploadSuccess, onUploadError]);
   225→
   226→  /**
   227→   * Format file size for display.
   228→   */
   229→  const formatFileSize = (bytes: number): string => {
   230→    if (bytes < 1024) return `${bytes} B`;
   231→    if (bytes < 1024 * 1024) return `${(bytes / 1024).toFixed(1)} KB`;
   232→    return `${(bytes / (1024 * 1024)).toFixed(2)} MB`;
   233→  };
   234→
   235→  return (
   236→    <Box>
   237→      {/* Drop zone */}
   238→      <Paper
   239→        elevation={isDragging ? 4 : 1}
   240→        onDragEnter={handleDragEnter}
   241→        onDragLeave={handleDragLeave}
   242→        onDragOver={handleDragOver}
   243→        onDrop={handleDrop}
   244→        sx={{
   245→          p: 4,
   246→          textAlign: 'center',
   247→          border: '2px dashed',
   248→          borderColor: isDragging
   249→            ? 'primary.main'
   250→            : fileError
   251→              ? 'error.main'
   252→              : 'grey.300',
   253→          borderRadius: 2,
   254→          backgroundColor: isDragging
   255→            ? 'action.hover'
   256→            : disabled
   257→              ? 'grey.100'
   258→              : 'background.paper',
   259→          cursor: disabled ? 'not-allowed' : 'pointer',
   260→          transition: 'all 0.2s ease',
   261→          '&:hover': {
   262→            borderColor: disabled ? 'grey.300' : 'primary.main',
   263→            backgroundColor: disabled ? 'grey.100' : 'action.hover',
   264→          },
   265→        }}
   266→        onClick={!disabled && !selectedFile ? handleBrowseClick : undefined}
   267→      >
   268→        <input
   269→          ref={fileInputRef}
   270→          type="file"
   271→          accept={acceptedFormats.join(',')}
   272→          onChange={handleInputChange}
   273→          style={{ display: 'none' }}
   274→          disabled={disabled}
   275→        />
   276→
   277→        {!selectedFile ? (
   278→          <>
   279→            <CloudUploadIcon
   280→              sx={{
   281→                fontSize: 48,
   282→                color: isDragging ? 'primary.main' : 'grey.400',
   283→                mb: 2,
   284→              }}
   285→            />
   286→            <Typography variant="h6" gutterBottom>
   287→              Arrastra tu archivo Excel aquí
   288→            </Typography>
   289→            <Typography variant="body2" color="text.secondary" gutterBottom>
   290→              o haz clic para seleccionar
   291→            </Typography>
   292→            <Typography variant="caption" color="text.secondary">
   293→              Formatos: {acceptedFormats.join(', ')} | Máximo: {maxSizeMB}MB
   294→            </Typography>
   295→          </>
   296→        ) : (
   297→          <Box>
   298→            <Box
   299→              sx={{
   300→                display: 'flex',
   301→                alignItems: 'center',
   302→                justifyContent: 'center',
   303→                gap: 1,
   304→                mb: 2,
   305→              }}
   306→            >
   307→              <FileIcon color="primary" />
   308→              <Typography variant="body1" fontWeight="medium">
   309→                {selectedFile.name}
   310→              </Typography>
   311→              <Chip
   312→                label={formatFileSize(selectedFile.size)}
   313→                size="small"
   314→                variant="outlined"
   315→              />
   316→              <IconButton
   317→                size="small"
   318→                onClick={(e) => {
   319→                  e.stopPropagation();
   320→                  handleClearFile();
   321→                }}
   322→                disabled={uploading}
   323→              >
   324→                <CloseIcon fontSize="small" />
   325→              </IconButton>
   326→            </Box>
   327→
   328→            {uploading && (
   329→              <Box sx={{ width: '100%', mb: 2 }}>
   330→                <LinearProgress variant="determinate" value={uploadProgress} />
   331→                <Typography variant="caption" color="text.secondary">
   332→                  {uploadProgress < 100 ? 'Procesando...' : 'Completado'}
   333→                </Typography>
   334→              </Box>
   335→            )}
   336→
   337→            <Button
   338→              variant="contained"
   339→              onClick={(e) => {
   340→                e.stopPropagation();
   341→                handleUpload();
   342→              }}
   343→              disabled={uploading || disabled}
   344→              startIcon={<CloudUploadIcon />}
   345→            >
   346→              {uploading ? 'Procesando...' : 'Cargar y Validar'}
   347→            </Button>
   348→          </Box>
   349→        )}
   350→      </Paper>
   351→
   352→      {/* File error */}
   353→      {fileError && (
   354→        <Alert severity="error" sx={{ mt: 2 }}>
   355→          <AlertTitle>Error</AlertTitle>
   356→          {fileError}
   357→        </Alert>
   358→      )}
   359→
   360→      {/* Validation errors */}
   361→      {validationErrors.length > 0 && (
   362→        <Alert
   363→          severity={validationErrors.length > 10 ? 'error' : 'warning'}
   364→          sx={{ mt: 2 }}
   365→        >
   366→          <AlertTitle>
   367→            {validationErrors.length > 10
   368→              ? 'Errores de validación'
   369→              : 'Advertencias de validación'}
   370→          </AlertTitle>
   371→          <Typography variant="body2" gutterBottom>
